js='''
const data=DATA;const audit=AUDIT;const chains=CHAINS;
const decisions=[['A9 · Collections and apiaries — owner direction recorded','Six-species capture/release journal, explicit specimen ingredients, bee colonies, flowering habitat, apiary frames, honeycomb, honey and wax. Full lifecycle and UI in plan §7.'],['A1 · Mana potions','Mana already exists. Approve an intended mana-spending use case, or leave six mana rows dormant.'],['A2 · Expanded hunting support — owner direction recorded','Author interaction policies for all 18 species: larger wild animals gain hunting; six small species use capture/release. No frog, insect or snail meat. Owned/ridden animals remain protected.'],['A3 · Flight','Greater only: 15 seconds, six tiles, safe landing, no walls/void/combat/mounts.'],['A4 · Potion conflicts','One skill, one regeneration and one utility effect; higher rank replaces, equal refreshes; 20-second use cooldown; stack 16.'],['A5 · Food scope','Approve core foods and review the optional confectionery/cooled cream set. No modern cans or gameplay item for every colour variant.'],['A6 · Sources and feed','New ingredients have explicit existing-merchant offers. Optional feed needs a persisted animal cooldown/interaction.'],['A7 · Stations and budgets','Keep generic estate production. Add typed production, dedicated alchemy cask, batch stations and proposed bronze prices.'],['A8 · Raw mini-buffs and skills','Small raw buffs and temporary activity benefits; no new XP tracks or Delve use.']];
const $=id=>document.getElementById(id);const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let page=0,apage=0;const PAGE=24,APAGE=80;window.reviewMetrics={imageErrors:0,gridErrors:0};
function icon(key,alt=false){const ic=data.icons[key];if(!ic)return '';const uid='icon-'+Math.random().toString(36).slice(2);return `<span class="iconbox ${alt?'alt':''}" id="${uid}" title="${escape(ic.label)}" data-icon="${escape(key)}" role="img" aria-label="${escape(ic.label)}"></span>`;}
function paint(){for(const el of document.querySelectorAll('[data-icon]:not([data-painted])')){el.dataset.painted='true';const ic=data.icons[el.dataset.icon];if(ic.grid){const c=document.createElement('canvas');const rows=ic.grid;c.width=rows[0].length;c.height=rows.length;c.setAttribute('aria-hidden','true');const ctx=c.getContext('2d');rows.forEach((row,y)=>[...row].forEach((p,x)=>{if(p!=='.'){if(!ic.palette[p])window.reviewMetrics.gridErrors++;ctx.fillStyle=ic.palette[p]||'#ff00ff';ctx.fillRect(x,y,1,1);}}));el.append(c);}else{const im=new Image();const size=el.classList.contains('alt')?48:64;const scale=size/ic.crop[2];im.alt='';im.onload=()=>{im.style.width=im.naturalWidth*scale+'px';im.style.height=im.naturalHeight*scale+'px';};im.onerror=()=>{window.reviewMetrics.imageErrors++;const e=document.createElement('span');e.className='error';e.textContent='Local art unavailable';el.append(e);};im.style.left=-ic.crop[0]*scale+'px';im.style.top=-ic.crop[1]*scale+'px';im.src='../../../'+ic.source;el.append(im);}}}
function inputs(i){return Object.entries(i.inputs).map(([id,n])=>`${n} × ${id.slice(5)}`).join(' + ')||i.source;}
function render(){const q=$('search').value.toLowerCase(),g=$('group').value,s=$('status').value;const rows=data.items.filter(i=>(!g||i.group===g)&&(!q||JSON.stringify(i).toLowerCase().includes(q))&&(!s||(s==='new'&&i.status!=='existing unchanged')||(s==='existing'&&i.status==='existing unchanged')||(s==='art'&&i.art.startsWith('ART NEEDED'))||(s==='conditional'&&i.status.startsWith('conditional'))));page=Math.min(page,Math.max(0,Math.ceil(rows.length/PAGE)-1));$('count').textContent=rows.length+' matching rows';$('page').textContent=`Page ${page+1} of ${Math.max(1,Math.ceil(rows.length/PAGE))}`;$('prev').disabled=page===0;$('next').disabled=(page+1)*PAGE>=rows.length;
$('cards').innerHTML=rows.slice(page*PAGE,(page+1)*PAGE).map(i=>{const ic=data.icons[i.icon];return `<article class="card" id="${escape(i.id)}"><span class="badge ${i.status!=='existing unchanged'?'pending':''}">${escape(i.status)}</span><h3>${escape(i.name)}</h3><code>${escape(i.id)}</code><div class="iconrow">${icon(i.icon)}${i.alternates.map(k=>icon(k,true)).join('')}</div>${i.art.startsWith('ART NEEDED')?`<p class="art-warning">${escape(i.art)}</p>`:''}<p>${escape(i.effect)}</p>${i.proposedRawBuff?`<p><strong>Proposed raw addition:</strong> ${escape(i.proposedRawBuff)}</p>`:''}<dl class="facts"><dt>Source / batch inputs</dt><dd>${escape(inputs(i))}</dd><dt>Produces / station</dt><dd>${i.output} portion(s) · ${escape(i.station)} · ${i.seconds}s</dd><dt>Progression</dt><dd>${escape(i.gate||i.tier)} · D${i.depth}</dd><dt>Stack / bronze</dt><dd>${i.stack} · Buy ${i.buy===null?'—':i.buy} / Sell ${i.sell}</dd></dl><details><summary>Icon provenance, alternatives & potion uses</summary><code>${escape(ic.source)}</code><p>${escape(ic.label)} ${ic.crop?' · crop '+ic.crop.join(','):''}</p><code>SHA-256 ${ic.sha256}</code>${i.alternates.map(k=>`<p>${escape(data.icons[k].label)}</p><code>${escape(data.icons[k].source)} ${data.icons[k].crop?'['+data.icons[k].crop.join(',')+']':''}</code>`).join('')}<p>${escape(i.potions.join(', ')||'No potion use')}</p></details></article>`;}).join('');paint();}
function auditRender(){const q=$('auditsearch').value.toLowerCase(),cat=$('category').value,disp=$('disposition').value;const rows=audit.filter(x=>(!cat||x[0]===cat)&&(!disp||x[4]===disp)&&(!q||x.join(' ').toLowerCase().includes(q)));apage=Math.min(apage,Math.max(0,Math.ceil(rows.length/APAGE)-1));$('auditcount').textContent=rows.length+' matching icons';$('auditpage').textContent=`Page ${apage+1} of ${Math.max(1,Math.ceil(rows.length/APAGE))}`;$('auditprev').disabled=apage===0;$('auditnext').disabled=(apage+1)*APAGE>=rows.length;
$('auditrows').innerHTML=rows.slice(apage*APAGE,(apage+1)*APAGE).map(x=>{const c=data.categories.find(c=>c.category===x[0]),key=x[0]+':'+x[1];if(!data.icons[key])data.icons[key]={label:key,source:c.source,crop:[x[6]%c.columns*16,Math.floor(x[6]/c.columns)*16,16,16]};return `<tr><td>${icon(key,true)}</td><td>${escape(x[0])} #${x[1]}</td><td>${escape(x[2])}<br>${escape(x[3])}</td><td>${escape(x[4])}</td><td>${escape(x[5])}</td></tr>`;}).join('');paint();}
for(const g of [...new Set(data.items.map(i=>i.group))].sort())$('group').add(new Option(g,g));for(const c of data.categories)$('category').add(new Option(c.category,c.category));for(const v of [...new Set(audit.map(x=>x[4]))].sort())$('disposition').add(new Option(v,v));
for(const id of ['search','group','status'])$(id).addEventListener('input',()=>{page=0;render();});for(const id of ['auditsearch','category','disposition'])$(id).addEventListener('input',()=>{apage=0;auditRender();});
$('prev').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};$('auditprev').onclick=()=>{apage--;auditRender();};$('auditnext').onclick=()=>{apage++;auditRender();};
for(const b of document.querySelectorAll('[data-tab]'))b.onclick=()=>{for(const k of ['items','audit','chains','decisions'])$(k).hidden=k!==b.dataset.tab;for(const n of document.querySelectorAll('[data-tab]'))n.setAttribute('aria-pressed',String(n===b));if(b.dataset.tab==='audit')auditRender();};
$('graphs').innerHTML=chains.map(([title,nodes])=>`<div class="chain"><h3>${escape(title)}</h3><div class="nodes" role="img" aria-label="${escape(nodes.join(' then '))}">${nodes.map(n=>`<span class="node">${escape(n)}</span>`).join('<span class="arrow" aria-hidden="true">→</span>')}</div></div>`).join('');$('decisionlist').innerHTML=decisions.map(([t,b])=>`<article class="decision"><h3>${escape(t)}</h3><p>${escape(b)}</p></article>`).join('');$('itemcount').textContent=data.items.length;
function hashSelect(){if(location.hash.startsWith('#item:')){$('search').value=decodeURIComponent(location.hash.slice(1));$('group').value='';$('status').value='';page=0;render();}}window.addEventListener('hashchange',hashSelect);render();hashSelect();
'''
js=js.replace('DATA',json.dumps(d,separators=(',',':')).replace('</','<\\/'),1).replace('AUDIT',json.dumps(audit,separators=(',',':')).replace('</','<\\/'),1).replace('CHAINS',json.dumps(chains),1)
(out/'index.html').write_text(head+'<script>\n'+js+'\n</script></html>\n')
print('rendered',len(d['items']),'rows',len(d['potions']),'potions',len(audit),'audit entries')
